import styled from '@emotion/styled';

export const Container = styled.div`
  background: white;
  padding: 24px;
  display: flex;
  flex-direction: column;
  width: 100%;
  border-radius: 16px;
  border: 1px solid rgba(20, 20, 20, 0.08);
`;

export const SectionGroup = styled.div`
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-bottom: 50px;
`;

export const TableCard = styled.div`
  width: 100%;
  background: #ffffff;
  border-radius: 12px;
  border: 1px solid rgba(20, 20, 20, 0.08);
  overflow: hidden;
`;

export const Toolbar = styled.div`
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 20px;
  height: 72px;
  box-sizing: border-box;
  border-bottom: 1px solid rgba(20, 20, 20, 0.08);
`;

export const ToolbarLeft = styled.div`
  display: flex;
  align-items: baseline;
  gap: 8px;
`;

export const ToolbarTitle = styled.span`
  font-family: 'Work Sans', sans-serif;
  font-size: 20px;
  font-weight: 600;
  line-height: 1.2;
  color: #141414;
`;

export const UnitLabel = styled.span`
  font-family: 'Work Sans', sans-serif;
  font-size: 14px;
  font-weight: 400;
  color: #757575;
`;

export const ToggleRow = styled.div`
  display: flex;
  align-items: center;
  gap: 8px;
`;

export const ToggleLabel = styled.span`
  font-family: 'Work Sans', sans-serif;
  font-size: 14px;
  font-weight: 400;
  color: #141414;
`;

export const DescriptionText = styled.p`
  margin: 0;
  color: #666666;
  font-size: 14px;
  line-height: 1.5;
`;

export const MetaRow = styled.div`
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  margin-top: 4px;
`;

export const Badge = styled.span<{ variant?: 'info' | 'success' | 'neutral' }>`
  display: inline-flex;
  align-items: center;
  padding: 2px 8px;
  border-radius: 4px;
  font-family: 'Work Sans', sans-serif;
  font-size: 12px;
  font-weight: 500;
  background-color: ${({ variant }) => {
    switch (variant) {
      case 'success':
        return '#E6F9E6';
      case 'info':
        return '#E0F2FE';
      default:
        return '#F2F2F2';
    }
  }};
  color: ${({ variant }) => {
    switch (variant) {
      case 'success':
        return '#007800';
      case 'info':
        return '#0369A1';
      default:
        return '#5C5C5C';
    }
  }};
`;
